	# Führe das eigentliche rbw Kommando mit allen übergebenen Argumenten aus.
	# LPEX speichert die Argumente nach arg_wrap in ARGS_EXTENSION_ARRAY.
	command rbw "${ARGS_EXTENSION_ARRAY[@]}"
}

