#!/bin/bash

function arguments {
	# Lade shared functions und entsperre rbw falls gesperrt.
	# `rbw unlocked` (im Check) dauert nur ~5 Millisekunden und bremst Autocompletion
	# nicht aus. Ist es gesperrt, poppt GPG für das Passwort auf.
	source "$PATH_EXTENSION_SOURCE/key/shared.sh"
	_unlock_rbw

	# Delegiert die gesamte Autocompletion und Argumentenübergabe an rbw
	arg_wrap "rbw"
}

#!/bin/bash

function extension_start {
	source "$(dirname "${BASH_SOURCE[0]}")/shared.sh"

	_check_cmd rbw

	# Stelle sicher, dass rbw entsperrt ist (bruchteil einer Millisekunde wenn schon entsperrt)
	_unlock_rbw

	# Führe das eigentliche rbw Kommando mit allen übergebenen Argumenten aus.
	# LPEX speichert die Argumente nach arg_wrap in ARGS_EXTENSION_ARRAY.
	command rbw "${ARGS_EXTENSION_ARRAY[@]}"
}

